import{_ as i,l,o as e,c as s,v as r,p as n,x as t,d as A,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"RSA 与 OAEP","description":"","frontmatter":{"title":"RSA 与 OAEP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rsa-oaep.md","filePath":"cs/rsa-oaep.md","lastUpdated":1789023840000}'),h={name:"cs/rsa-oaep.md"};function c(E,a,P,m,S,_){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="rsa-与-oaep" tabindex="-1">RSA 与 OAEP <a class="header-anchor" href="#rsa-与-oaep" aria-label="Permalink to &quot;RSA 与 OAEP&quot;">​</a></h1><div class="epigraph"><p>RSA 函数是模幂；直接加密短消息既不确定也不抗选择密文。OAEP 用哈希做随机化填充，把 RSA 收成在随机预言机模型下可达到 CCA 目标的信封零件。</p><footer>—— Rivest, Shamir and Adleman, 1978；Bellare and Rogaway, Optimal Asymmetric Encryption Padding, EUROCRYPT 1994；PKCS #1 v2</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/birthday-attack">生日攻击</a>钉了哈希宽度。主干<a href="/cs/pubkey-envelope">公钥信封</a>与<a href="/cs/dh-vs-rsa">DH 与 RSA 分工</a>已把 RSA 当封装选项。缺口是<strong>明文不能直接当模幂输入</strong>：必须填充。本课收 OAEP，不重推欧拉定理。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教科书 RSA \\(c=m^e\\bmod n\\) 确定、可乘性，选择密文下可被操纵。OAEP：用随机种子和哈希把 \\(m\\) 扩成类似一次一密的掩码块再模幂。TLS 1.3 已不用 RSA 密钥传输，但签名与遗留封装仍要理解填充。缺口是填充合同，不是再讲因数分解叙事。</p><h3 id="签名填充是另一套" tabindex="-1">签名填充是另一套 <a class="header-anchor" href="#签名填充是另一套" aria-label="Permalink to &quot;签名填充是另一套&quot;">​</a></h3><p>PSS 与 PKCS#1 v1.5 签名填充下一课攻击面才对照。加密填充与签名填充不能混用同一密钥语义而不加域分离。</p><p><span class="marginnote">Bellare–Rogaway OAEP。Fujisaki–Okamoto 等是同类「把陷门置换收成 CCA」的框架，本课只钉 OAEP。不要发明 arXiv 编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 RSA 陷门置换角色：公钥 \\((n,e)\\) 公开，私钥 \\(d\\) 解幂。OAEP 的两轮 Feistel 式掩码（用 \\(G,H\\) 哈希）。对照：哈希宽度受生日界约束，种子必须真随机。</p>',12)),(e(),n(p,null,{default:t(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%B6%88%E6%81%AF%22%5D%20--%3E%20OAEP%5B%22OAEP%20%E9%9A%8F%E6%9C%BA%E5%8C%96%E5%A1%AB%E5%85%85%22%5D%0A%20%20R%5B%22%E9%9A%8F%E6%9C%BA%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20OAEP%0A%20%20OAEP%20--%3E%20POW%5B%22%E6%A8%A1%E5%B9%82%20e%22%5D%0A%20%20POW%20--%3E%20C%5B%22%E5%AF%86%E6%96%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信封仍是：RSA 只封对称键，数据走 AEAD。OAEP 让封装在理想哈希下可归约到 RSA 陷门。实现必须常数时间模幂与严格的填充校验——校验失败不可区分，否则又是预言机。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给选择密文操纵的步骤。下一课 RSA 攻击面：填充实现、共模、广播、小指数，全部当失败模式与防御，不当配方。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生日界约束填充里的哈希；RSA 要随机化填充。</li><li>OAEP 把陷门置换收成 CCA 向的封装。</li><li>TLS 1.3 不用 RSA 传输密钥；遗留与签名仍要填充。</li><li>下一课：填充与数论误用的攻击面清单。</li><li>出处：Rivest, Shamir and Adleman, 1978；Bellare and Rogaway, 1994；PKCS #1。</li></ul>',8))])}const f=i(h,[["render",c]]);export{R as __pageData,f as default};
